#!/usr/bin/env python3
"""A small, original Doxygen-compatible command line reimplementation.

This program is intentionally focused on the externally visible behaviours that
are practical for tests: command line modes, configuration template handling,
style/layout/emoji outputs, config updating/comparison, and a lightweight
HTML/LaTeX documentation run for small source trees.
"""

from __future__ import annotations

import html as html_mod
import os
import re
import shlex
import shutil
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

VERSION = "1.17.0"
REVISION = "9135bd68ddc9ea65023d967c75048a7a86a5d495"
VERSION_FULL = f"{VERSION} ({REVISION})"
SQLITE_VERSION = "3.42.0"

ROOT = Path(__file__).resolve().parent
STATIC_DIR = ROOT / "data" / "static"
ASSET_DIR = ROOT / "data" / "assets"

TAG_RE = re.compile(r"^\s*([A-Z][A-Z0-9_]*)\s*(\+?=)\s*(.*)$")

STRING_TAGS = {
    "PROJECT_NAME", "PROJECT_NUMBER", "PROJECT_BRIEF", "PROJECT_LOGO",
