    "RTF_OUTPUT", "MAN_OUTPUT", "XML_OUTPUT", "DOCBOOK_OUTPUT",
    "WARN_FORMAT", "WARN_LOGFILE", "OUTPUT_TEXT_DIRECTION", "CHM_FILE",
    "QCH_FILE", "QHP_NAMESPACE", "QHP_VIRTUAL_FOLDER", "QHP_CUST_FILTER_NAME",
    "QHG_LOCATION", "TAGFILE", "GENERATE_TAGFILE", "PERL_PATH",
    "MSCGEN_TOOL", "DOT_PATH", "DIA_PATH", "PLANTUML_JAR_PATH",
