    "ALWAYS_DETAILED_SEC", "JAVADOC_AUTOBRIEF", "QT_AUTOBRIEF",
    "OPTIMIZE_OUTPUT_FOR_C", "OPTIMIZE_OUTPUT_JAVA", "HAVE_DOT",
