LIST_LIKE_TAGS = {
    "INPUT", "FILE_PATTERNS", "EXCLUDE", "EXCLUDE_PATTERNS", "EXCLUDE_SYMBOLS",
    "EXAMPLE_PATH", "IMAGE_PATH", "INCLUDE_PATH", "INCLUDE_FILE_PATTERNS",
    "PREDEFINED", "EXPAND_AS_DEFINED", "ALIASES", "ABBREVIATE_BRIEF",
