def progress_printer(quiet: bool, debug_time: bool = False):
    counter = {"i": 1}
    def emit(msg: str) -> None:
        if quiet:
            return
        if debug_time:
            # Deterministic approximation of Doxygen's elapsed-time prefix.
            t = counter["i"] / 1000.0
            counter["i"] += 1
            sys.stdout.write(f"{t:.3f} sec: {msg}\n")
        else:
            sys.stdout.write(msg + "\n")
    return emit


def cmd_comment_block(file_name: str) -> int:
    try:
        text = Path(file_name).read_text(encoding="utf-8", errors="replace")
    except OSError as ex:
        eprint(f"error: {ex}\n")
        return 1
    doc = clean_doc_comment(text)
    sys.stdout.write(f"<p>{html_escape(doc)}</p>\n")
    return 0


def cmd_document(args: Sequence[str], *, debug_time: bool = False) -> int:
    # Developer comment mode.
    if "-c" in args:
        idx = list(args).index("-c")
        if idx + 1 < len(args):
            return cmd_comment_block(args[idx + 1])
    # Unknown options in documentation runs.
    known_doc_opts = {"-q", "-s", "-m", "-b"}
    skip_next_for = {"-d", "-c"}
    skip = False
    config_name: Optional[str] = None
    for a in args:
        if skip:
            skip = False
            continue
        if a in skip_next_for:
            skip = True
            continue
        if a in known_doc_opts:
            continue
        if a == "-":
            config_name = a
            continue
        if a.startswith("-"):
            print_help()
            eprint(f'error: Unknown option "{a}"\n')
            return 1
        if config_name is None:
            config_name = a
    if config_name is None:
        config_name = "Doxyfile"

    if config_name == "-":
        config_text = sys.stdin.read()
        cfg_path = Path("-")
    else:
        cfg_path = Path(config_name)
        if not cfg_path.exists():
            print_help()
            if config_name == "Doxyfile":
                eprint("error: Doxyfile not found and no input file specified!\n")
            else:
                eprint(f"error: configuration file {config_name} not found!\n")
            return 1
        config_text = cfg_path.read_text(encoding="utf-8", errors="replace")
    parsed = parse_config_text(config_text, config_name, base=DEFAULTS, expand_env=True, warn_unknown=True)
    for w in parsed.warnings:
        eprint(w)
    values = parsed.values
    if "-q" in args:
        values["QUIET"] = "YES"
    quiet = config_bool(values, "QUIET", False)
    project = config_string(values, "PROJECT_NAME", "My Project") or "My Project"
    output_dir_raw = config_string(values, "OUTPUT_DIRECTORY", "")
    out_dir = Path(output_dir_raw) if output_dir_raw else Path(".")
    emit = progress_printer(quiet, debug_time=debug_time)
    emit(f"Doxygen version used: {VERSION_FULL}")
    if output_dir_raw and not out_dir.exists():
        out_dir.mkdir(parents=True, exist_ok=True)
        emit(f"Notice: Output directory '{output_dir_raw}' does not exist. I have created it for you.")
    elif output_dir_raw:
        out_dir.mkdir(parents=True, exist_ok=True)
    files_paths, searched_dirs = collect_input_files(values, None if config_name == "-" else cfg_path)
    for msg in PROGRESS_PREFIX:
        emit(msg)
    for d in searched_dirs:
        emit(f"Searching for files in directory {d}")
    for msg in PROGRESS_MIDDLE[:2]:
        emit(msg)
    for f in files_paths:
        emit(f"Preprocessing {f.resolve()}...")
        emit(f"Parsing file {f.resolve()}...")
    for msg in PROGRESS_MIDDLE[2:]:
        emit(msg)

    file_infos = [parse_source_file(p, rel_for_file(p)) for p in files_paths]

    if config_bool(values, "GENERATE_HTML", True):
        # Per-file/class generation messages at approximately the original spot.
        emit("Generating style sheet...")
        emit("Generating search indices...")
        emit("Generating example documentation...")
        emit("Generating file sources...")
        for fi in file_infos:
            emit(f"Generating code for file {fi.rel}...")
        emit("Generating file documentation...")
        for fi in file_infos:
            emit(f"Generating docs for file {fi.rel}...")
        emit("Generating page documentation...")
        emit("Generating group documentation...")
        emit("Generating class documentation...")
        for ci in [c for fi in file_infos for c in fi.classes]:
            emit(f"Generating docs for compound {ci.name}...")
        for msg in PROGRESS_END[10:]:
            emit(msg)
        generate_html(out_dir, project, file_infos, values)
    else:
        for msg in PROGRESS_END:
            emit(msg)

    if config_bool(values, "GENERATE_LATEX", True):
        generate_latex(out_dir, project, file_infos)

    if not files_paths and config_bool(values, "WARNINGS", True):
        eprint("warning: No files to be processed, please check your settings, in particular INPUT, FILE_PATTERNS, and RECURSIVE\n")
    emit("type lookup cache used 0/65536 hits=0 misses=0")
    emit("symbol lookup cache used 0/65536 hits=0 misses=0")
    emit("finished...")
    return 0


# ---------------------------------------------------------------------------
# Main dispatch


def handle_debug_args(args: List[str]) -> Tuple[Optional[int], List[str], bool]:
    """Return (immediate_exit_code, cleaned_args, debug_time)."""
    if "-d" not in args:
        return None, args, False
    cleaned: List[str] = []
    debug_time = False
    i = 0
    while i < len(args):
        if args[i] != "-d":
            cleaned.append(args[i])
            i += 1
            continue
        if i + 1 >= len(args) or args[i + 1].startswith("-"):
            sys.stdout.write(debug_text())
            return 0, args, False
        spec = args[i + 1]
        if spec not in DEBUG_LEVELS:
            sys.stdout.write(f'option "-d" has unknown debug specifier: "{spec}".\n')
            sys.stdout.write(debug_text())
            return 1, args, False
        if spec == "time":
            debug_time = True
        # Keep -d/spec in cleaned only for doc option skipping? Easier remove it.
        i += 2
    return None, cleaned, debug_time


def main(argv: Sequence[str]) -> int:
    args = list(argv[1:])

    # Help and version options take precedence and ignore extra arguments.
    if any(a in {"-h", "-?", "--help"} for a in args):
        print_help()
        return 0
    if any(a in {"-v", "--version"} for a in args):
        sys.stdout.write(VERSION_FULL + "\n")
        return 0
    if "-V" in args:
        sys.stdout.write(VERSION_FULL + "\n")
        sys.stdout.write(f"    with sqlite3 {SQLITE_VERSION}.\n")
        return 0

    debug_exit, cleaned_args, debug_time = handle_debug_args(args)
    if debug_exit is not None:
        return debug_exit
    args = cleaned_args

    strip_comments = "-s" in args

    if "-g" in args:
        return cmd_generate(args, strip_comments)
    if "-u" in args:
        return cmd_update(args, strip_comments)
    if "-l" in args:
        return cmd_layout(args)
    if "-w" in args:
        return cmd_write_style(args)
    if "-e" in args:
        return cmd_extension(args)
    if "-x_noenv" in args:
        return cmd_compare(args, noenv=True)
    if "-x" in args:
        return cmd_compare(args, noenv=False)
    if "-f" in args:
        return cmd_emoji(args)

    # Unknown top-level long/short options before a doc run without config.
    if args and args[0].startswith("-") and args[0] not in {"-q", "-s", "-m", "-b", "-"}:
        print_help()
        eprint(f'error: Unknown option "{args[0]}"\n')
        return 1

    return cmd_document(args, debug_time=debug_time)


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            raise SystemExit(1)
