SOURCE_EXTS = {
    ".c", ".cc", ".cxx", ".cpp", ".c++", ".h", ".hh", ".hpp", ".hxx",
    ".java", ".cs", ".php", ".py", ".f", ".f90", ".for", ".d", ".idl",
    ".vhd", ".vhdl", ".md", ".markdown",
}


def static_bytes(name: str) -> bytes:
    p = STATIC_DIR / name
    return p.read_bytes()


def static_text(name: str) -> str:
    return static_bytes(name).decode("utf-8", errors="replace")


def write_bytes_target(target: str, data: bytes) -> None:
    if target == "-":
        sys.stdout.buffer.write(data)
    else:
        path = Path(target)
        if path.parent != Path(""):
            path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)


def write_text_target(target: str, data: str) -> None:
    write_bytes_target(target, data.encode("utf-8"))


def program_name() -> str:
    return sys.argv[0]


def help_text() -> str:
    text = static_text("help.txt")
    return text.replace("/workspace/executable", program_name())


def print_help() -> None:
    sys.stdout.write(help_text())


def debug_text() -> str:
    return static_text("debug.txt")


def eprint(s: str) -> None:
    sys.stderr.write(s)


# ---------------------------------------------------------------------------
# Configuration parsing/formatting


def strip_inline_comment(line: str) -> str:
    """Remove a Doxygen-style # comment, respecting double quotes."""
    in_quote = False
    escaped = False
    out: List[str] = []
    for ch in line:
        if escaped:
            out.append(ch)
            escaped = False
            continue
        if ch == "\\":
            out.append(ch)
            escaped = True
            continue
        if ch == '"':
            in_quote = not in_quote
            out.append(ch)
            continue
        if ch == "#" and not in_quote:
            break
        out.append(ch)
    return "".join(out).rstrip()


def logical_config_lines(text: str) -> Iterable[Tuple[int, str]]:
    lines = text.splitlines()
    i = 0
    n = len(lines)
    while i < n:
        start = i + 1
        part = strip_inline_comment(lines[i]).rstrip()
        if not part.strip():
            i += 1
            continue
        parts: List[str] = []
        while True:
            continued = part.rstrip().endswith("\\")
            if continued:
                part = part.rstrip()[:-1].rstrip()
            parts.append(part.strip())
            if not continued:
                break
            i += 1
            if i >= n:
                break
            part = strip_inline_comment(lines[i]).rstrip()
        logical = " ".join(p for p in parts if p)
        if logical:
            yield start, logical
        i += 1


def expand_environment(value: str) -> str:
    # Observed Doxygen expands $(VAR). It does not expand ${VAR} in -x output.
    def repl(m: re.Match[str]) -> str:
        return os.environ.get(m.group(1), "")
    return re.sub(r"\$\(([A-Za-z_][A-Za-z0-9_]*)\)", repl, value)


def shlex_split(value: str) -> List[str]:
    if value is None:
        return []
    value = value.strip()
    if not value:
        return []
    try:
        return shlex.split(value, posix=True)
    except ValueError:
        # Fall back to whitespace splitting for malformed quotes; Doxygen is
        # permissive enough for many old config files.
        return value.replace('"', '').split()


def shell_join_tokens(tokens: Sequence[str], quote_alias: bool = True, tag: str = "") -> List[str]:
    res: List[str] = []
    for tok in tokens:
        need_quote = False
        if tok == "":
            need_quote = True
        if any(c.isspace() for c in tok):
            need_quote = True
        if tag == "ALIASES" and quote_alias:
            need_quote = True
        if tok.startswith("#") or tok.endswith("\\"):
            need_quote = True
        if need_quote:
            escaped = tok.replace("\\", "\\\\").replace('"', '\\"')
            res.append(f'"{escaped}"')
        else:
            res.append(tok)
    return res


def canonical_value(tag: str, raw: str) -> object:
    raw = (raw or "").strip()
    if tag in BOOL_TAGS:
        toks = shlex_split(raw)
        return (toks[0].upper() if toks else "")
    toks = shlex_split(raw)
    if tag in STRING_TAGS and tag not in LIST_LIKE_TAGS:
        if len(toks) <= 1:
            return toks[0] if toks else ""
        return " ".join(toks)
    return tuple(toks)


@dataclass
class ParsedConfig:
    values: Dict[str, str]
    specified: set = field(default_factory=set)
    warnings: List[str] = field(default_factory=list)


def parse_config_text(
    text: str,
    filename: str = "Doxyfile",
    *,
    base: Optional[Dict[str, str]] = None,
    expand_env: bool = False,
    warn_unknown: bool = True,
) -> ParsedConfig:
    values = dict(base or {})
    specified: set = set()
    warnings: List[str] = []
    known = set(DEFAULTS.keys()) if "DEFAULTS" in globals() else None
    for lineno, logical in logical_config_lines(text):
        m = TAG_RE.match(logical)
        if not m:
            continue
        tag, op, value = m.group(1), m.group(2), m.group(3).strip()
        if expand_env:
            value = expand_environment(value)
        if known is not None and tag not in known:
            if warn_unknown:
                warnings.append(
                    f"warning: ignoring unsupported tag '{tag}' at line {lineno}, file {filename}\n"
                )
            continue
        old = values.get(tag, "")
        if op == "+=":
            value = (old + " " + value).strip() if old else value
        values[tag] = value
        specified.add(tag)
    return ParsedConfig(values, specified, warnings)


def parse_defaults_and_order() -> Tuple[Dict[str, str], List[str]]:
    text = static_text("Doxyfile_s")
    values: Dict[str, str] = {}
    order: List[str] = []
    # Parse without using DEFAULTS/known.
    for _, logical in logical_config_lines(text):
        m = TAG_RE.match(logical)
        if not m:
            continue
        tag, op, value = m.group(1), m.group(2), m.group(3).strip()
        if tag not in order:
            order.append(tag)
        if op == "+=":
            old = values.get(tag, "")
            value = (old + " " + value).strip() if old else value
        values[tag] = value
    return values, order


DEFAULTS, TAG_ORDER = parse_defaults_and_order()
KNOWN_TAGS = set(DEFAULTS.keys())


def format_value_items(tag: str, raw: str, *, quote_alias: bool = True) -> List[str]:
    raw = (raw or "").strip()
    if not raw:
        return []
    toks = shlex_split(raw)
    if not toks:
        return [raw]
    if tag in STRING_TAGS and tag not in LIST_LIKE_TAGS:
        # Doxygen keeps PROJECT_NAME with spaces as a single quoted string.
        val = toks[0] if len(toks) == 1 else " ".join(toks)
        return shell_join_tokens([val], quote_alias=False, tag=tag)
    return shell_join_tokens(toks, quote_alias=quote_alias, tag=tag)


def format_assignment(tag: str, raw: str, *, quote_alias: bool = True) -> str:
    prefix_empty = f"{tag:<23}="
    items = format_value_items(tag, raw, quote_alias=quote_alias)
    if not items:
        return prefix_empty
    prefix = f"{tag:<23}= "
    if len(items) == 1:
        return prefix + items[0]
    cont_prefix = " " * 25
    out = [prefix + items[0] + " \\"]
    for item in items[1:-1]:
        out.append(cont_prefix + item + " \\")
    out.append(cont_prefix + items[-1])
    return "\n".join(out)


def update_template(template: str, values: Dict[str, str], specified: set) -> str:
    lines = template.splitlines(keepends=True)
    out: List[str] = []
    i = 0
    while i < len(lines):
        line = lines[i]
        m = TAG_RE.match(line.rstrip("\n"))
        if not m:
            out.append(line)
            i += 1
            continue
        tag = m.group(1)
        # Determine this physical continuation block.
        block = [line]
        i += 1
        while block[-1].rstrip("\n").rstrip().endswith("\\") and i < len(lines):
            block.append(lines[i])
            i += 1
        if tag in specified:
            out.append(format_assignment(tag, values.get(tag, ""), quote_alias=True) + "\n")
        else:
            out.extend(block)
    return "".join(out)


def config_get(values: Dict[str, str], tag: str, default: str = "") -> str:
    return values.get(tag, DEFAULTS.get(tag, default))


def config_bool(values: Dict[str, str], tag: str, default: bool = False) -> bool:
    raw = config_get(values, tag, "YES" if default else "NO")
    toks = shlex_split(raw)
    if not toks:
        return default
    return toks[0].upper() in {"YES", "TRUE", "1", "ON"}


def config_tokens(values: Dict[str, str], tag: str) -> List[str]:
    return shlex_split(config_get(values, tag, ""))


def config_string(values: Dict[str, str], tag: str, default: str = "") -> str:
    raw = config_get(values, tag, default).strip()
    toks = shlex_split(raw)
    if not toks:
        return default
    if tag in STRING_TAGS and tag not in LIST_LIKE_TAGS:
        return toks[0] if len(toks) == 1 else " ".join(toks)
    return " ".join(toks)


# ---------------------------------------------------------------------------
# CLI modes


def find_mode_name(args: Sequence[str], names: Sequence[str]) -> Optional[str]:
    for a in args:
        if a in names:
            return a
    return None


def following_value(args: Sequence[str], opt: str, *, default: Optional[str] = None, skip_options: bool = False) -> Optional[str]:
    try:
        idx = list(args).index(opt)
    except ValueError:
        return default
    for a in args[idx + 1:]:
        if skip_options and a != "-" and a.startswith("-"):
            continue
        return a
    return default


def first_config_after(args: Sequence[str], opt: str, default: str) -> str:
    try:
        idx = list(args).index(opt)
    except ValueError:
        return default
    for a in args[idx + 1:]:
        if a == "-":
            return a
        if a.startswith("-"):
            continue
        return a
    return default


def cmd_generate(args: Sequence[str], strip_comments: bool) -> int:
    name = first_config_after(args, "-g", "Doxyfile")
    data_name = "Doxyfile_s" if strip_comments else "Doxyfile"
    data = static_bytes(data_name)
    if name == "-":
        sys.stdout.buffer.write(data)
        return 0
    write_bytes_target(name, data)
    sys.stdout.write(f"\n\nConfiguration file '{name}' created.\n\n")
    sys.stdout.write("Now edit the configuration file and enter\n\n")
    if name == "Doxyfile":
        sys.stdout.write("  doxygen\n\n")
    else:
        sys.stdout.write(f"  doxygen {name}\n\n")
    sys.stdout.write("to generate the documentation for your project\n")
    return 0


def cmd_update(args: Sequence[str], strip_comments: bool) -> int:
    name = first_config_after(args, "-u", "Doxyfile")
    if name == "-":
        text = sys.stdin.read()
        parsed = parse_config_text(text, "-", base=DEFAULTS, expand_env=False, warn_unknown=True)
        for w in parsed.warnings:
            eprint(w)
        tmpl = static_text("Doxyfile_s" if strip_comments else "Doxyfile")
        sys.stdout.write(update_template(tmpl, parsed.values, parsed.specified))
        return 0
    path = Path(name)
    if not path.exists():
        print_help()
        if name == "Doxyfile":
            eprint("error: Doxyfile not found and no input file specified!\n")
        else:
            eprint(f"error: configuration file {name} not found!\n")
        return 1
    text = path.read_text(encoding="utf-8", errors="replace")
    parsed = parse_config_text(text, name, base=DEFAULTS, expand_env=False, warn_unknown=True)
    for w in parsed.warnings:
        eprint(w)
    tmpl = static_text("Doxyfile_s" if strip_comments else "Doxyfile")
    path.write_text(update_template(tmpl, parsed.values, parsed.specified), encoding="utf-8")
    sys.stdout.write(f"\n\nConfiguration file '{name}' updated.\n\n")
    return 0


def cmd_layout(args: Sequence[str]) -> int:
    name = following_value(args, "-l", default="DoxygenLayout.xml", skip_options=False)
    if name is None:
        name = "DoxygenLayout.xml"
    write_bytes_target(name, static_bytes("layout.xml"))
    return 0


def cmd_extension(args: Sequence[str]) -> int:
    try:
        idx = list(args).index("-e")
    except ValueError:
        return 1
    if idx + 1 >= len(args):
        eprint('error: option "-e" is missing format specifier rtf.\n')
        return 1
    fmt = args[idx + 1]
    if fmt != "rtf":
        eprint('error: option "-e" has invalid format specifier.\n')
        return 1
    if idx + 2 >= len(args):
        eprint('error: option "-e rtf" is missing an extensions file name\n')
        return 1
    write_bytes_target(args[idx + 2], static_bytes("rtfext.cfg"))
    return 0


def choose_css_for_config(config_file: Optional[str]) -> bytes:
    if not config_file or config_file == "-":
        return static_bytes("custom.css")
    try:
        text = Path(config_file).read_text(encoding="utf-8", errors="replace")
    except OSError:
        return static_bytes("custom.css")
    parsed = parse_config_text(text, config_file, base=DEFAULTS, expand_env=False, warn_unknown=False)
    style = config_string(parsed.values, "HTML_COLORSTYLE", "TOGGLE").upper()
    if style == "DARK":
        return static_bytes("custom_dark.css")
    if style == "LIGHT":
        return static_bytes("custom_light.css")
    return static_bytes("custom.css")


def cmd_write_style(args: Sequence[str]) -> int:
    try:
        idx = list(args).index("-w")
    except ValueError:
        return 1
    if idx + 1 >= len(args):
        eprint('error: option "-w" is missing format specifier rtf, html or latex\n')
        return 1
    fmt = args[idx + 1]
    if fmt not in {"rtf", "html", "latex"}:
        eprint(f'error: Illegal format specifier "{fmt}": should be one of rtf, html or latex\n')
        return 1
    rest = list(args[idx + 2:])
    if fmt == "rtf":
        if len(rest) < 1:
            eprint('error: option "-w rtf" is missing a style sheet file name\n')
            return 1
        write_bytes_target(rest[0], static_bytes("rtfstyle.cfg"))
        return 0
    if fmt == "html":
        if len(rest) < 3:
            eprint('error: option "-w html" does not have enough arguments\n')
            return 1
        config_file = rest[3] if len(rest) >= 4 else None
        outputs = [
            (rest[0], static_bytes("header.html")),
            (rest[1], static_bytes("footer.html")),
            (rest[2], choose_css_for_config(config_file)),
        ]
    else:
        if len(rest) < 3:
            eprint('error: option "-w latex" does not have enough arguments\n')
            return 1
        outputs = [
            (rest[0], static_bytes("header.tex")),
            (rest[1], static_bytes("footer.tex")),
            (rest[2], static_bytes("doxygen.sty")),
        ]
    for target, data in outputs:
        write_bytes_target(target, data)
    return 0


def cmd_emoji(args: Sequence[str]) -> int:
    try:
        idx = list(args).index("-f")
    except ValueError:
        return 1
    if idx + 1 >= len(args):
        eprint('error: option "-f" is missing list specifier.\n')
        return 1
    spec = args[idx + 1]
    if spec != "emoji":
        eprint('error: option "-f" has invalid list specifier.\n')
        return 1
    if idx + 2 >= len(args):
        eprint('error: option "-f emoji" is missing an output file name\n')
        return 1
    write_bytes_target(args[idx + 2], static_bytes("emoji.txt"))
    return 0


def cmd_compare(args: Sequence[str], noenv: bool) -> int:
    opt = "-x_noenv" if noenv else "-x"
    name = first_config_after(args, opt, "Doxyfile")
    if name == "-":
        text = sys.stdin.read()
        filename = "-"
    else:
        path = Path(name)
        if not path.exists():
            print_help()
            if name == "Doxyfile":
                eprint("error: Doxyfile not found and no input file specified!\n")
            else:
                eprint(f"error: configuration file {name} not found!\n")
            return 1
        text = path.read_text(encoding="utf-8", errors="replace")
        filename = name
    parsed = parse_config_text(text, filename, base=DEFAULTS, expand_env=not noenv, warn_unknown=True)
    for w in parsed.warnings:
        eprint(w)
    sys.stdout.write(f"# Difference with default Doxyfile {VERSION_FULL}\n")
    for tag in TAG_ORDER:
        val = parsed.values.get(tag, DEFAULTS.get(tag, ""))
        default = DEFAULTS.get(tag, "")
        if canonical_value(tag, val) != canonical_value(tag, default):
            quote_alias = noenv or tag != "ALIASES"
            sys.stdout.write(format_assignment(tag, val, quote_alias=quote_alias) + "\n")
    return 0


# ---------------------------------------------------------------------------
# Lightweight documentation generation


@dataclass
class Member:
    name: str
    signature: str
    ret: str = ""
    doc: str = ""


@dataclass
class ClassInfo:
    name: str
    kind: str = "class"
    doc: str = ""
    members: List[Member] = field(default_factory=list)


@dataclass
class FileInfo:
    path: Path
    rel: str
    doc: str = ""
    classes: List[ClassInfo] = field(default_factory=list)
    functions: List[Member] = field(default_factory=list)


def clean_doc_comment(comment: str) -> str:
    if not comment:
        return ""
    s = comment.strip()
    if s.startswith("/**") or s.startswith("/*!"):
        s = s[3:]
        if s.endswith("*/"):
            s = s[:-2]
    elif s.startswith("///") or s.startswith("//!":
        pass
    lines = []
    for line in s.splitlines():
        line = line.strip()
        if line.startswith("///") or line.startswith("//!":
            line = line[3:]
        if line.startswith("*"):
            line = line[1:]
        line = line.strip()
        line = re.sub(r"^[\\@](brief|file|param|return|returns)\b\s*", "", line)
        if line:
            lines.append(line)
    return " ".join(lines).strip()


def preceding_comment(text: str, pos: int) -> str:
    prefix = text[:pos]
    # Skip whitespace between declaration and comment.
    mspace = re.search(r"\s*$", prefix)
    end = mspace.start() if mspace else len(prefix)
    prefix = prefix[:end]
    m = re.search(r"(/\*\*.*?\*/|/\*!.*?\*/|(?:(?://[/!].*\n)\s*)+)$", prefix, re.S)
    if not m:
        return ""
    return clean_doc_comment(m.group(1))


def parse_source_file(path: Path, rel: str) -> FileInfo:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        text = ""
    info = FileInfo(path=path, rel=rel)
    fm = re.search(r"(/\*\*.*?(?:\\|@)file.*?\*/|/\*!.*?(?:\\|@)file.*?\*/)", text, re.S)
    if fm:
        info.doc = clean_doc_comment(fm.group(1))
    # Python support: triple quoted docstring plus class/def.
    if path.suffix == ".py":
        for m in re.finditer(r"(?m)^\s*class\s+([A-Za-z_][A-Za-z0-9_]*)", text):
            ci = ClassInfo(name=m.group(1), kind="class", doc=preceding_comment(text, m.start()))
            # simple methods indented under class
            info.classes.append(ci)
        for m in re.finditer(r"(?m)^\s*def\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(([^)]*)\)", text):
            info.functions.append(Member(name=m.group(1), signature=f"{m.group(1)}({m.group(2)})", doc=preceding_comment(text, m.start())))
        return info
    # C/C++/Java-ish class blocks.
    for m in re.finditer(r"\b(class|struct|interface)\s+([A-Za-z_][A-Za-z0-9_:]*)[^;{]*\{", text):
        kind, name = m.group(1), m.group(2).split("::")[-1]
        doc = preceding_comment(text, m.start())
        start = m.end()
        depth = 1
        i = start
        while i < len(text) and depth:
            if text[i] == "{":
                depth += 1
            elif text[i] == "}":
                depth -= 1
            i += 1
        body = text[start:i - 1]
        ci = ClassInfo(name=name, kind="class" if kind == "interface" else kind, doc=doc)
        for mm in re.finditer(
            r"(?m)(?:^|[;{}]\s*)([A-Za-z_][\w:<>,~*&\s]*?)\s+([A-Za-z_~][\w~]*)\s*\(([^;{}()]*)\)\s*(?:const\s*)?[;{]",
            body,
        ):
            ret = " ".join(mm.group(1).split())
            mn = mm.group(2)
            if mn in {"if", "for", "while", "switch", "return"}:
                continue
            sig = f"{mn}({mm.group(3).strip()})"
            abs_pos = start + mm.start()
            ci.members.append(Member(name=mn, signature=sig, ret=ret, doc=preceding_comment(text, abs_pos)))
        info.classes.append(ci)
    # Remove class bodies to avoid duplicating member functions as globals.
    scrub = re.sub(r"\b(class|struct|interface)\s+[A-Za-z_][A-Za-z0-9_:]*[^;{]*\{.*?\}\s*;?", "", text, flags=re.S)
    for m in re.finditer(
        r"(?m)(?:^|[;{}]\s*)([A-Za-z_][\w:<>,~*&\s]*?)\s+([A-Za-z_][\w]*)\s*\(([^;{}()]*)\)\s*(?:const\s*)?[;{]",
        scrub,
    ):
        ret = " ".join(m.group(1).split())
        name = m.group(2)
        if name in {"if", "for", "while", "switch", "return"}:
            continue
        sig = f"{name}({m.group(3).strip()})"
        info.functions.append(Member(name=name, signature=sig, ret=ret, doc=preceding_comment(text, m.start())))
    return info


def html_escape(s: str) -> str:
    return html_mod.escape(s or "", quote=True)


def file_page_name(rel: str) -> str:
    base = Path(rel).name
    # Doxygen's common encoding for foo.h is foo_8h.html.
    encoded = base.replace("_", "__").replace(".", "_8").replace("-", "_2d")
    return f"{encoded}.html"


def source_page_name(rel: str) -> str:
    return file_page_name(rel).replace(".html", "_source.html")


def class_page_name(cls: ClassInfo) -> str:
    prefix = "struct" if cls.kind == "struct" else "class"
    return f"{prefix}{cls.name}.html"


def page_header(project: str, title: str, active: str = "") -> str:
    project_e = html_escape(project)
    return f'''<!DOCTYPE html>
