def write_html_page(path: Path, project: str, title: str, body: str) -> None:
    path.write_text(page_header(project, title) + body + page_footer(), encoding="utf-8")


def copy_tree_contents(src: Path, dst: Path) -> None:
    if not src.exists():
        return
    for p in src.rglob("*"):
        if p.is_dir():
            continue
        rel = p.relative_to(src)
        target = dst / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(p, target)


def generate_html(out_dir: Path, project: str, files: List[FileInfo], values: Dict[str, str]) -> None:
    html_dir = out_dir / config_string(values, "HTML_OUTPUT", "html")
    html_dir.mkdir(parents=True, exist_ok=True)
    # Static assets observed from Doxygen runs.
    copy_tree_contents(ASSET_DIR / "html", html_dir)
    (html_dir / "doxygen.css").write_bytes(choose_css_for_config(None))
    (html_dir / "search").mkdir(exist_ok=True)
    classes = [c for fi in files for c in fi.classes]
    functions = [fn for fi in files for fn in fi.functions] + [m for c in classes for m in c.members]

    # Main page.
    body = f'<div class="header"><div class="headertitle"><div class="title">{html_escape(project)} Documentation</div></div></div>\n'
    if files:
        body += '<p>Documentation generated from the input files.</p>\n'
    write_html_page(html_dir / "index.html", project, "Main Page", body)

    # Class list and per-class pages.
    rows = []
    for c in classes:
        rows.append(f'<tr><td class="indexkey"><a class="el" href="{class_page_name(c)}">{html_escape(c.name)}</a></td><td class="indexvalue">{html_escape(c.doc)}</td></tr>')
    body = '<div class="header"><div class="headertitle"><div class="title">Class List</div></div></div>\n<table class="directory">\n' + "\n".join(rows) + "\n</table>\n"
    write_html_page(html_dir / "annotated.html", project, "Class List", body)
    write_html_page(html_dir / "classes.html", project, "Class Index", body)
    write_html_page(html_dir / "hierarchy.html", project, "Class Hierarchy", '<div class="title">Class Hierarchy</div>\n')
    for c in classes:
        memrows = []
        for m in c.members:
            memrows.append(f'<tr class="memitem"><td class="memItemLeft">{html_escape(m.ret)}&#160;</td><td class="memItemRight"><a class="el" href="#{html_escape(m.name)}">{html_escape(m.signature)}</a></td></tr>')
        detail = []
        for m in c.members:
            detail.append(f'<h2 class="memtitle" id="{html_escape(m.name)}">{html_escape(m.name)}()</h2><div class="memdoc"><p>{html_escape(m.doc)}</p></div>')
        body = f'<div class="header"><div class="headertitle"><div class="title">{html_escape(c.name)} Class Reference</div></div></div>\n'
        if c.doc:
            body += f'<div class="textblock"><p>{html_escape(c.doc)}</p></div>\n'
        if memrows:
            body += '<h2>Public Member Functions</h2><table class="memberdecls">' + "\n".join(memrows) + '</table>\n'
            body += '<h2>Member Function Documentation</h2>\n' + "\n".join(detail)
        write_html_page(html_dir / class_page_name(c), project, f"{c.name} Class Reference", body)
        members_body = '<ul>' + ''.join(f'<li>{html_escape(m.name)}</li>' for m in c.members) + '</ul>'
        write_html_page(html_dir / f"{class_page_name(c).replace('.html','')}-members.html", project, f"{c.name} Members", members_body)
        (html_dir / f"{class_page_name(c).replace('.html','.js')}").write_text(
            f"var {class_page_name(c).replace('.html','')} = [\n" +
            ",\n".join(f'    [ "{m.name}", "{class_page_name(c)}#{m.name}", null ]' for m in c.members) +
            "\n];",
            encoding="utf-8",
        )

    # File list and per-file pages.
    file_rows = []
    for fi in files:
        file_rows.append(f'<tr><td class="indexkey"><a class="el" href="{file_page_name(fi.rel)}">{html_escape(fi.rel)}</a></td><td class="indexvalue">{html_escape(fi.doc)}</td></tr>')
    body = '<div class="header"><div class="headertitle"><div class="title">File List</div></div></div>\n<table class="directory">\n' + "\n".join(file_rows) + "\n</table>\n"
    write_html_page(html_dir / "files.html", project, "File List", body)
    for fi in files:
        decls = []
        for c in fi.classes:
            decls.append(f'<tr><td class="memItemLeft">{c.kind}&#160;</td><td class="memItemRight"><a class="el" href="{class_page_name(c)}">{html_escape(c.name)}</a></td></tr>')
        for fn in fi.functions:
            decls.append(f'<tr class="memitem"><td class="memItemLeft">{html_escape(fn.ret)}&#160;</td><td class="memItemRight"><a class="el" href="#{html_escape(fn.name)}">{html_escape(fn.signature)}</a></td></tr>')
        details = []
        for fn in fi.functions:
            details.append(f'<h2 class="memtitle" id="{html_escape(fn.name)}">{html_escape(fn.name)}()</h2><div class="memdoc"><p>{html_escape(fn.doc)}</p></div>')
        body = f'<div class="header"><div class="headertitle"><div class="title">{html_escape(Path(fi.rel).name)} File Reference</div></div></div>\n'
        if decls:
            body += '<table class="memberdecls">' + "\n".join(decls) + '</table>\n'
        if fi.doc:
            body += f'<div class="textblock"><p>{html_escape(fi.doc)}</p></div>\n'
        body += "\n".join(details)
        write_html_page(html_dir / file_page_name(fi.rel), project, f"{Path(fi.rel).name} File Reference", body)
        try:
            src = fi.path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            src = ""
        src_body = f'<div class="fragment"><pre class="fragment">{html_escape(src)}</pre></div>\n'
        write_html_page(html_dir / source_page_name(fi.rel), project, f"{Path(fi.rel).name} Source File", src_body)
        (html_dir / file_page_name(fi.rel).replace(".html", ".js")).write_text("var file = [];", encoding="utf-8")

    # Member/global indices.
    func_items = ''.join(f'<li>{html_escape(fn.name)}</li>' for fn in functions)
    write_html_page(html_dir / "functions.html", project, "Class Members", f'<h1>Class Members</h1><ul>{func_items}</ul>')
    write_html_page(html_dir / "functions_func.html", project, "Class Member Functions", f'<h1>Functions</h1><ul>{func_items}</ul>')
    global_items = ''.join(f'<li>{html_escape(fn.name)}</li>' for fi in files for fn in fi.functions)
    write_html_page(html_dir / "globals.html", project, "File Members", f'<h1>File Members</h1><ul>{global_items}</ul>')
    write_html_page(html_dir / "globals_func.html", project, "File Members", f'<h1>Functions</h1><ul>{global_items}</ul>')

    # JavaScript navigation/search data.
    annotated = "var annotated_dup =\n[\n" + ",\n".join(
        f'    [ "{c.name}", "{class_page_name(c)}", "{class_page_name(c).replace(".html", "")}" ]' for c in classes
    ) + "\n];"
    (html_dir / "annotated_dup.js").write_text(annotated, encoding="utf-8")
    files_dup = "var files_dup =\n[\n" + ",\n".join(
        f'    [ "{Path(fi.rel).name}", "{file_page_name(fi.rel)}", null ]' for fi in files
    ) + "\n];"
    (html_dir / "files_dup.js").write_text(files_dup, encoding="utf-8")
    menu = 'var menudata={children:[\n{text:"Main Page",url:"index.html"},\n{text:"Classes",url:"annotated.html"},\n{text:"Files",url:"files.html"}\n]}'
    (html_dir / "menudata.js").write_text(menu, encoding="utf-8")
    nav = f'''var NAVTREE =
[
  [ "{project}", "index.html", [
    [ "Classes", "annotated.html", "annotated_dup" ],
    [ "Files", "files.html", "files_dup" ]
  ] ]
];

var NAVTREEINDEX =
[
"index.html"
];

const SYNCONMSG = 'click to disable panel synchronization';
const SYNCOFFMSG = 'click to enable panel synchronization';
const LISTOFALLMEMBERS = 'List of all members';
'''
    (html_dir / "navtreedata.js").write_text(nav, encoding="utf-8")
    (html_dir / "navtreeindex0.js").write_text("var NAVTREEINDEX0 = {};", encoding="utf-8")
    crawl_links = ['<a href="index.html"/>'] + [f'<a href="{class_page_name(c)}"/>' for c in classes] + [f'<a href="{file_page_name(fi.rel)}"/>' for fi in files]
    (html_dir / "doxygen_crawl.html").write_text("\n".join(crawl_links), encoding="utf-8")
    search_dir = html_dir / "search"
    search_dir.mkdir(exist_ok=True)
    (search_dir / "searchdata.js").write_text("var indexSectionsWithContent = {};\nvar indexSectionNames = {};\nvar indexSectionLabels = {};", encoding="utf-8")
    (search_dir / "all_0.js").write_text("var searchData=[];", encoding="utf-8")
    if classes:
        (search_dir / "classes_0.js").write_text("var searchData=[" + ",".join(f'["{c.name.lower()}",["{c.name}","../{class_page_name(c)}",1,""]]' for c in classes) + "];", encoding="utf-8")
    if files:
        (search_dir / "files_0.js").write_text("var searchData=[];", encoding="utf-8")
    if functions:
        (search_dir / "functions_0.js").write_text("var searchData=[];", encoding="utf-8")


def generate_latex(out_dir: Path, project: str, files: List[FileInfo]) -> None:
    latex_dir = out_dir / "latex"
