    (latex_dir / "doxygen.sty").write_bytes(static_bytes("doxygen.sty"))
    title = project.replace("_", "\\_")
    body = [
        r"\documentclass[twoside]{book}",
        r"\usepackage{doxygen}",
        r"\begin{document}",
        rf"\title{{{title} Documentation}}",
        r"\maketitle",
        r"\tableofcontents",
    ]
