def collect_input_files(values: Dict[str, str], config_path: Optional[Path]) -> Tuple[List[Path], List[str]]:
    inputs = config_tokens(values, "INPUT")
    if not inputs:
        inputs = ["."]
    recursive = config_bool(values, "RECURSIVE", False)
    base_dir = Path.cwd()
    if config_path and config_path != Path("-") and config_path.parent != Path(""):
        # Doxygen treats relative INPUT paths relative to current working
        # directory, not necessarily config path, in common CLI use; keep cwd.
        base_dir = Path.cwd()
    files: List[Path] = []
    searched_dirs: List[str] = []
    for item in inputs:
        p = Path(item)
        if not p.is_absolute():
            p = base_dir / p
        if p.is_dir():
            searched_dirs.append(str(p.resolve()))
            iterator = p.rglob("*") if recursive else p.glob("*")
            for q in iterator:
                if q.is_file() and q.suffix.lower() in SOURCE_EXTS:
                    # Avoid scanning generated output directories.
                    parts = set(q.parts)
                    if {"html", "latex", "docs"} & parts and not config_tokens(values, "INPUT"):
                        continue
                    files.append(q)
        elif p.is_file():
            if p.suffix.lower() in SOURCE_EXTS or not p.suffix:
                files.append(p)
    # Unique in stable order.
    seen = set()
    uniq: List[Path] = []
    for f in files:
        rp = str(f.resolve())
        if rp not in seen:
            seen.add(rp)
            uniq.append(f)
    return uniq, searched_dirs


def rel_for_file(path: Path) -> str:
    try:
        return str(path.resolve().relative_to(Path.cwd().resolve()))
    except Exception:
        return str(path)


